--- clean/crates/crypto/circuits/src/group/ownership_inspection.rs
+++ overlay/crates/crypto/circuits/src/group/ownership_inspection.rs
@@ -0,0 +1,204 @@
+//! Read-only bounded capture of one explicitly selected authorization variable-base loop.
+use super::{Point, Scalar};
+use crate::scalar::inspection::Observed;
+use commonware_cryptography::zk::circuit::{BoolVar, CircuitIdx, Var};
+use std::{cell::RefCell, marker::PhantomData, rc::Rc};
+
+#[derive(Clone, Copy, Default, PartialEq, Eq)]
+pub enum ObservationKind { #[default] Owner, RnkDh }
+#[derive(Clone, PartialEq, Eq)]
+pub struct RnkBindings {
+    pub inputs: [Observed; 9],
+    pub hash: Observed,
+    pub commitment: Observed,
+    pub regulated: Observed,
+    pub registered: Observed,
+    pub effective_nk: Observed,
+}
+#[derive(Clone, PartialEq, Eq)]
+pub struct Report {
+    pub base: [Observed; 2],
+    pub bits: Vec<CircuitIdx>,
+    pub twice: [Observed; 2],
+    pub triple: [Observed; 2],
+    /// Before, first double, second double, selected digit, result; x/y pairs.
+    pub windows: Vec<[[Observed; 2]; 5]>,
+    pub window_bits: Vec<[CircuitIdx; 2]>,
+    /// Existing numerator x/y, denominator x/y, quotient x/y.
+    pub quotients: Vec<[Observed; 6]>,
+    pub output: [Observed; 2],
+    pub target: Option<[Observed; 2]>,
+    pub nonidentity_inverse: Option<Observed>,
+    pub rnk: Option<RnkBindings>,
+}
+#[derive(Default)]
+struct State {
+    kind: ObservationKind,
+    active: bool,
+    calls: usize,
+    quotients: Vec<[Observed; 6]>,
+    report: Option<Report>,
+    overflow: bool,
+}
+thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+pub struct Capture { _thread: PhantomData<Rc<()>> }
+impl Drop for Capture { fn drop(&mut self) { STATE.with(|s| *s.borrow_mut() = None); } }
+pub fn begin() -> anyhow::Result<Capture> { begin_kind(ObservationKind::Owner) }
+pub fn begin_rnk_dh() -> anyhow::Result<Capture> { begin_kind(ObservationKind::RnkDh) }
+fn begin_kind(kind: ObservationKind) -> anyhow::Result<Capture> {
+    STATE.with(|s| {
+        let mut s = s.borrow_mut();
+        anyhow::ensure!(s.is_none(), "nested ownership capture");
+        *s = Some(State { kind, ..State::default() });
+        Ok(Capture { _thread: PhantomData })
+    })
+}
+pub struct Scope { _thread: PhantomData<Rc<()>> }
+impl Drop for Scope {
+    fn drop(&mut self) { STATE.with(|s| if let Some(s) = s.borrow_mut().as_mut() { s.active = false; }); }
+}
+pub(crate) fn scope() -> Option<Scope> { selected_scope(ObservationKind::Owner) }
+pub(crate) fn rnk_scope() -> Option<Scope> { selected_scope(ObservationKind::RnkDh) }
+fn selected_scope(kind: ObservationKind) -> Option<Scope> {
+    STATE.with(|s| {
+        let mut s = s.borrow_mut();
+        let s = s.as_mut()?;
+        if s.kind != kind { return None; }
+        assert!(!s.active, "nested ownership scope");
+        s.calls += 1;
+        s.active = true;
+        Some(Scope { _thread: PhantomData })
+    })
+}
+fn observed(v: &Var<'_, Scalar>) -> Observed {
+    match v.inspect_circuit_idx() {
+        Some(i) => Observed::Source(i),
+        None => Observed::Native(v.inspect_native().expect("invalid ownership variable").clone()),
+    }
+}
+pub(super) fn point(p: &Point<Var<'_, Scalar>>) -> [Observed; 2] {
+    [observed(&p.x), observed(&p.y)]
+}
+pub(super) fn active() -> bool {
+    STATE.with(|s| s.borrow().as_ref().is_some_and(|s| s.active))
+}
+pub(super) fn quotient(values: [&Var<'_, Scalar>; 6]) {
+    STATE.with(|s| {
+        if let Some(s) = s.borrow_mut().as_mut().filter(|s| s.active) {
+            if s.quotients.len() < 380 {
+                s.quotients.push(values.map(observed));
+            } else { s.overflow = true; }
+        }
+    });
+}
+pub(super) fn finish(base: &Point<Var<'_, Scalar>>, bits: &[BoolVar<'_, Scalar>],
+    twice: &Point<Var<'_, Scalar>>, triple: &Point<Var<'_, Scalar>>,
+    windows: Vec<[[Observed; 2]; 5]>, window_bits: Vec<[CircuitIdx; 2]>, output: &Point<Var<'_, Scalar>>) {
+    STATE.with(|s| {
+        if let Some(s) = s.borrow_mut().as_mut().filter(|s| s.active) {
+            assert!(s.report.is_none(), "duplicate ownership loop");
+            s.report = Some(Report { base: point(base), bits: bits.iter().map(|b|
+                b.var().inspect_circuit_idx().expect("ownership bit must have source")).collect(),
+                twice: point(twice), triple: point(triple), windows, window_bits,
+                quotients: std::mem::take(&mut s.quotients), output: point(output), target: None, nonidentity_inverse: None, rnk: None });
+        }
+    });
+}
+pub(crate) fn target(target: &Point<Var<'_, Scalar>>) {
+    STATE.with(|s| {
+        if let Some(s) = s.borrow_mut().as_mut().filter(|s| s.active) {
+            let report = s.report.as_mut().expect("ownership target before loop");
+            assert!(report.target.is_none(), "duplicate ownership target");
+            report.target = Some(point(target));
+        }
+    });
+}
+pub(super) fn nonidentity(x: &Var<'_, Scalar>, inverse: &Var<'_, Scalar>) {
+    STATE.with(|s| {
+        if let Some(s) = s.borrow_mut().as_mut().filter(|s| s.active && s.kind == ObservationKind::RnkDh) {
+            let report = s.report.as_mut().expect("RNK nonidentity before loop");
+            assert!(report.nonidentity_inverse.is_none(), "duplicate RNK nonidentity");
+            assert!(observed(x) == report.output[0], "RNK nonidentity output role mismatch");
+            report.nonidentity_inverse = Some(observed(inverse));
+        }
+    });
+}
+pub(crate) fn rnk_bindings(inputs: &[Var<'_, Scalar>; 9], hash: &Var<'_, Scalar>,
+    commitment: &Var<'_, Scalar>, regulated: &Var<'_, Scalar>, registered: &Var<'_, Scalar>,
+    effective_nk: &Var<'_, Scalar>) {
+    STATE.with(|s| {
+        if let Some(s) = s.borrow_mut().as_mut().filter(|s| s.active && s.kind == ObservationKind::RnkDh) {
+            let report = s.report.as_mut().expect("RNK binding before loop");
+            assert!(report.rnk.is_none(), "duplicate RNK bindings");
+            assert!([observed(&inputs[0]), observed(&inputs[1])] == report.output, "RNK hash DH input role mismatch");
+            report.rnk = Some(RnkBindings { inputs: inputs.each_ref().map(observed),
+                hash: observed(hash), commitment: observed(commitment), regulated: observed(regulated),
+                registered: observed(registered), effective_nk: observed(effective_nk) });
+        }
+    });
+}
+pub fn take() -> anyhow::Result<Report> {
+    STATE.with(|s| {
+        let mut s = s.borrow_mut();
+        let s = s.as_mut().ok_or_else(|| anyhow::anyhow!("ownership capture absent"))?;
+        anyhow::ensure!(!s.active && s.calls == 1 && !s.overflow, "ownership scope/overflow mismatch");
+        let report = s.report.take().ok_or_else(|| anyhow::anyhow!("ownership loop absent"))?;
+        anyhow::ensure!(report.bits.len() == 252 && report.windows.len() == 126 &&
+            report.window_bits.len() == 126 && report.quotients.len() == 380,
+            "ownership loop shape mismatch");
+        match s.kind {
+            ObservationKind::Owner => anyhow::ensure!(report.target.is_some() &&
+                report.nonidentity_inverse.is_none() && report.rnk.is_none(), "owner endpoint shape mismatch"),
+            ObservationKind::RnkDh => anyhow::ensure!(report.target.is_none() &&
+                report.nonidentity_inverse.is_some() && report.rnk.is_some(), "RNK output/binding shape mismatch"),
+        }
+        for (window, bits) in report.window_bits.iter().enumerate() {
+            let low = 2 * (125 - window);
+            anyhow::ensure!(*bits == [report.bits[low], report.bits[low + 1]],
+                "ownership window bit order mismatch");
+        }
+        Ok(report)
+    })
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    #[test]
+    fn exclusive_scope_cleanup() {
+        let capture = begin().unwrap();
+        assert!(begin().is_err());
+        { let _scope = scope().unwrap(); assert!(active()); }
+        assert!(!active());
+        assert!(take().is_err());
+        drop(capture);
+        let _ = std::panic::catch_unwind(|| { let _capture = begin().unwrap(); let _scope = scope(); panic!("cleanup"); });
+        let _capture = begin().unwrap();
+        assert!(!active());
+    }
+    #[test]
+    fn selected_occurrence_and_rnk_panic_cleanup() {
+        {
+            let _capture = begin_rnk_dh().unwrap();
+            assert!(scope().is_none());
+            assert!(!active());
+            STATE.with(|s| assert_eq!(s.borrow().as_ref().unwrap().calls, 0));
+            { let _scope = rnk_scope().unwrap(); assert!(active()); }
+            STATE.with(|s| assert_eq!(s.borrow().as_ref().unwrap().calls, 1));
+            assert!(take().is_err());
+        }
+        {
+            let _capture = begin().unwrap();
+            assert!(rnk_scope().is_none());
+            STATE.with(|s| assert_eq!(s.borrow().as_ref().unwrap().calls, 0));
+        }
+        let _ = std::panic::catch_unwind(|| {
+            let _capture = begin_rnk_dh().unwrap();
+            let _scope = rnk_scope().unwrap();
+            panic!("RNK cleanup");
+        });
+        let _capture = begin_rnk_dh().unwrap();
+        assert!(!active());
+    }
+
+}
